[ExtensionOf(tableStr(METWHSPhysDimUOMSite))]
final class METWHSPhysDimUOMSite_Extension
{
}

Method.Source:
/// <summary>
/// Finds a METWHSPhysDimUOMSite record by primary key.
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_uom">UnitOfMeasureSymbol</param>
/// <param name = "_siteId">InventSiteId</param>
/// <param name = "_wHSPhysDimId">WHSPhysDimId</param>
/// <returns></returns>
public static METWHSPhysDimUOMSite find(ItemId _itemId, UnitOfMeasureSymbol _uom, InventSiteId _siteId, WHSPhysDimId _wHSPhysDimId = '')
{
    METWHSPhysDimUOMSite physDimUOMSite;

    select firstonly physDimUOMSite
        where physDimUOMSite.ItemId == _itemId
            && physDimUOMSite.UOM == _uom
            && physDimUOMSite.SiteId == _siteId
            && physDimUOMSite.PhysDimId == _wHSPhysDimId;

    return physDimUOMSite;
}
